def split_csv(line):
    fields = []
    field = []
    in_quotes = False
    i = 0
    while i < len(line):
        char = line[i]
        if in_quotes:
            if char == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    field.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                field.append(char)
        else:
            if char == '"':
                in_quotes = True
            elif char == ',':
                fields.append(''.join(field))
                field = []
            else:
                field.append(char)
        i += 1
    fields.append(''.join(field))
    return fields
